  const throttle = Number(pressed("ArrowUp", "KeyW")) - Number(pressed("ArrowDown", "KeyS"));
  const steer = Number(pressed("ArrowLeft", "KeyA")) - Number(pressed("ArrowRight", "KeyD"));
