  p.z += dz * speed * dt;
  const r = Math.hypot(p.x, p.z);
  const edge = clamp(r, inner + 1, outer - 1);
  if (r !== edge) {
    p.multiplyScalar(edge / r);
    speed *= Math.exp(-5 * dt);
  }

